  *     res.writeHead(404);
  *     res.end();
  *   });
  * });
  * ```
  */
 export function createNodeMiddleware(
   appFn: ApplicationFunction,
   { probot = createProbot(), webhooksPath } = {} as MiddlewareOptions,
