44.       ? rebindLog(options.log)
45.       : rebindLog(this.probotApp.log.child({ name: "server" }));
46. 
47.     this.state = {
48.       cwd: options.cwd || process.cwd(),
49.       port: options.port,
50.       host: options.host,
51.       webhookPath: options.webhookPath || defaultWebhooksPath,
52.       webhookProxy: options.webhookProxy,
