56.     this.expressApp.use(
57.       "/probot/static/",
58.       express.static(join(__dirname, "..", "..", "static")),
59.     );
60.     this.expressApp.use(
61.       createWebhooksMiddleware(this.probotApp.webhooks, {
62.         path: this.state.webhookPath,
63.       }),
64.     );
